/** Scoped single-row read; `null` when the label is missing or in another org. */
export async function findLabel(
  orgId: OrgId,
  labelId: LabelId,
): Promise<IssueLabel | null> {
  const row = getDb()
    .select()
    .from(labels)
    .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, labelId)))
    .get();
  return row ? toLabel(row) : null;
}

/**
 * Moves every assignment of `sourceLabelId` onto `targetLabelId`, then drops
 * the source label. Runs in one transaction. Returns how many issues carried
 * the source label before the merge.
 */
export async function mergeLabelInto(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<number> {
  return getDb().transaction((tx) => {
    const carried = tx
      .select({ issueId: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .all();

    if (carried.length > 0) {
      // Issues that already carry the target hit the unique index and are skipped.
      tx.insert(issueLabels)
        .values(
          carried.map(({ issueId }) => ({
            orgId,
            issueId,
            labelId: targetLabelId,
          })),
        )
        .onConflictDoNothing()
        .run();
    }

    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .run();
    tx.delete(labels)
      .where(
        and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)),
      )
      .run();

    return carried.length;
  });
}

/** Replaces the whole label set of one issue in a single round trip. */

